func numIslands(_ grid: [[Character]]) -> Int {
    var g = grid, count = 0
    let rows = g.count, cols = g[0].count
    for r in 0..<rows {
        for c in 0..<cols where g[r][c] == "1" {
            count += 1
            var stack = [(r, c)]
            g[r][c] = "0"
            while let (cr, cc) = stack.popLast() {
                for (nr, nc) in [(cr + 1, cc), (cr - 1, cc), (cr, cc + 1), (cr, cc - 1)]
                where nr >= 0 && nr < rows && nc >= 0 && nc < cols && g[nr][nc] == "1" {
                    g[nr][nc] = "0"
                    stack.append((nr, nc))
                }
            }
        }
    }
    return count
}
